 if(item.scopeType==='pupil')return 'Individual pupil';
 if(item.scopeType==='legacy')return 'Migrated v40';
 const names=(item.classIds||[]).map(id=>classes.find(c=>c.id===id)?.name||id);return names.join(', ')||'Selected classes';
