 const value=id=>host.querySelector(id)?.value||'';
 return {scrollY:window.scrollY,search:value('#feeSearch'),pupilId:host.querySelector('#feePupil')?.dataset.studentId||'',detailState,reportFilters:{year:value('#feeReportYear'),term:value('#feeReportTerm'),classId:value('#feeReportClass'),categoryId:value('#feeReportCategory'),status:value('#feeReportStatus'),dataMode:value('#feeReportDataMode')},statement:{studentId:value('#feeStatementPupil'),year:value('#feeStatementYear'),term:value('#feeStatementTerm'),dataMode:value('#feeStatementDataMode')}};
